class CinbaseConfigRecordListTests(unittest.TestCase):

    def setUp(self):
        from cinbase.config import CONFIG_RECORDS, IME_DIRS
        self.records = CONFIG_RECORDS
        self.ime_dirs = IME_DIRS
        self.page = read_text(os.path.join(CINBASE_DIR, "config", "config.htm"))
        self.script = read_text(os.path.join(CINBASE_DIR, "config", "js", "config.js"))

    def shipped(self, ime):
        path = os.path.join(CONFIG_DIR, ime, "config", "config.json")
        with open(path, encoding="utf-8") as handle:
            return json.load(handle)

    def test_init_defaults_derive_from_the_record_list(self):
        keys = [row[0] for row in self.records]
        self.assertEqual(len(keys), len(set(keys)), "one row per key")
        cfg = fresh_config()
        for key, default, control, affecting, _mirror, effect, _overrides in self.records:
            self.assertTrue(hasattr(cfg, key), "%s has no __init__ default" % key)
            self.assertEqual(getattr(cfg, key), default, "%s default" % key)
            self.assertIn(control, ("checkbox", "text", "select", "radio", "none"))
            self.assertIsInstance(affecting, bool)
            if affecting:
                self.assertIn(effect, ("reload", "flag", "extend", "priority", "selkeys"))
            else:
                self.assertIsNone(effect)

    def test_shipped_jsons_match_derived_defaults(self):
        from cinbase.config import shipped_defaults_for, write_shipped_configs
        # the eight of the original quartet, plus chebihua on the same seam
        self.assertEqual(
            ("chearray", "checj", "chedayi", "cheez", "cheliu",
             "chephonetic", "chepinyin", "chesimplex"),
            self.ime_dirs[:8])
        self.assertEqual(9, len(self.ime_dirs))
        with tempfile.TemporaryDirectory() as temp_dir:
            inner = os.path.join(temp_dir, "python")
            os.makedirs(inner)
            write_shipped_configs(inner)
            for ime in self.ime_dirs:
                derived = shipped_defaults_for(ime)
                data = self.shipped(ime)
                self.assertEqual(derived, data,
                                 "%s ships values the record list does not" % ime)
                # the committed file is the writer's bytes, byte for byte
                with open(os.path.join(inner, "input_methods", ime,
                                       "config", "config.json"), encoding="utf-8") as handle:
                    written = handle.read()
                with open(os.path.join(CONFIG_DIR, ime, "config", "config.json"),
                          encoding="utf-8") as handle:
                    self.assertEqual(written, handle.read(),
                                     "%s drifted from the derived bytes" % ime)

    def test_the_settings_page_exposes_record_controls(self):
        page = re.sub(r"<!--.*?-->", "", self.page, flags=re.S)
        named = set(re.findall(r'<(?:input|select)\b[^>]*?name="([^"]+)"', page))
        control_keys = {row[0] for row in self.records if row[2] != "none"}
        # no stray control on the page, and every control row is on it:
        # config.htm carries the checkbox/text/select rows, the PAGE_SIDE_ONLY
        # rows live in the per-Service shell or are built by the script
        self.assertTrue(named.issubset(control_keys),
                        "page control %s is not a record" % sorted(named - control_keys))
        self.assertEqual(control_keys - named, set(PAGE_SIDE_ONLY))
        for key, path in PAGE_SIDE_ONLY.items():
            self.assertRegex(read_text(path), r'(?:id|name)="%s"' % key,
                             "no control for %s on the page surface" % key)
        # the script reads the defaults off the served record list instead
        # of restating them: the option rows and the index fallback all go
        # through pythonDefaults / selKeysData
        self.assertIn("pythonDefaults[\"selKeyType\"]", self.script)
        self.assertIn("selKeysData", self.script)
        self.assertNotIn("var selSelKeys", self.script)
        for key in ("candPerPage", "candPerRow", "candFontWeight"):
            self.assertIn('pythonDefaults["%s"]' % key, self.script)

    def test_table_affecting_rows_drive_the_diff(self):
        self.assertEqual(TABLE_AFFECTING_KEYS,
                         tuple(row[0] for row in self.records if row[3]))
        import cinbase

        def pair(temp_dir):
            cfg = fresh_config()
            cfg.imeDirName = "chesimplex"
            sentinel = object()
            table = SimpleNamespace(loading=False, curCinType=cfg.selCinType,
                                    ignorePrivateUseArea=cfg.ignorePrivateUseArea,
                                    userExtendTable=cfg.userExtendTable,
                                    priorityExtendTable=cfg.priorityExtendTable,
                                    selKeys=cfg.getSelKeys(), cin=sentinel, future=None)
            cbTS = mock.MagicMock()
            cbTS.cfg = cfg
            cbTS.cin = sentinel
            cbTS.reLoadCinTable = False
            cbTS.imeDirName = "chesimplex"
            cbTS.cinFileList = ["simplex.json", "simplex5.json"]
            cbTS.jsondir = cfg.getJsonDir()
            cfg.update()  # settle the version tuple before the first call
            cbTS.configVersion = tuple(cfg.getVersion())
            return cfg, table, cbTS

        def call(cfg, table, cbTS):
            cinbase.CinBase.checkConfigChange(cbTS, table, mock.MagicMock(), mock.MagicMock())

        with tempfile.TemporaryDirectory() as temp_dir:
            with mock.patch.dict(os.environ, {"APPDATA": temp_dir}):
                # a plain diff row: the table reloads and the loader starts
                cfg, table, cbTS = pair(temp_dir)
                cfg.selCinType = 1
                call(cfg, table, cbTS)
                self.assertIsNotNone(table.future, "selCinType diff must reload")
                self.assertEqual(1, table.curCinType)

                # the mirror-named row for the private-use-area flag
                cfg, table, cbTS = pair(temp_dir)
                cfg.ignorePrivateUseArea = False
                call(cfg, table, cbTS)
                self.assertIsNotNone(table.future,
                                     "ignorePrivateUseArea diff must reload")

                # the cfg-side flag row clears itself and saves
                cfg, table, cbTS = pair(temp_dir)
                with open(cfg.getConfigFile(), "w", encoding="utf-8") as handle:
                    json.dump({}, handle)
                cfg.reLoadTable = True
                call(cfg, table, cbTS)
                self.assertFalse(cfg.reLoadTable, "the flag must clear after the diff")
                self.assertIsNotNone(table.future, "reLoadTable must reload")

                # the extend row refreshes the table
                cfg, table, cbTS = pair(temp_dir)
                cfg.userExtendTable = True
                call(cfg, table, cbTS)
                self.assertIsNotNone(table.future, "userExtendTable diff must reload")

                # the priority row only reloads while the extend table is on
                cfg, table, cbTS = pair(temp_dir)
                cfg.userExtendTable = True
                table.userExtendTable = True
                cfg.priorityExtendTable = True
                call(cfg, table, cbTS)
                self.assertIsNotNone(table.future,
                                     "priorityExtendTable must reload with the extend table on")

                # the sel-keys row re-declares the selection keys, no table reload
                cfg, table, cbTS = pair(temp_dir)
                cfg.selKeyType = 1
                call(cfg, table, cbTS)
                self.assertEqual("0123456789", table.selKeys)
                self.assertTrue(cbTS.isSelKeysChanged)
                self.assertIsNone(table.future, "the sel-keys row must not reload the table")

                # a non-table-affecting key changes nothing
                cfg, table, cbTS = pair(temp_dir)
                call(cfg, table, cbTS)
                cbTS.configVersion = tuple(cfg.getVersion())
                cfg.fontSize = 15
                call(cfg, table, cbTS)
                self.assertIsNone(table.future, "fontSize is not table-affecting")
                self.assertEqual("1234567890", table.selKeys)

    def test_one_new_record_propagates_everywhere(self):
        # keyboardLayout entered the list as an orphan (it sat in the shipped
        # JSONs but never in __init__); one row now drives all projections.
        row = next(r for r in self.records if r[0] == "keyboardLayout")
        self.assertEqual((0, "radio", False), (row[1], row[2], row[3]))
        self.assertEqual(0, fresh_config().keyboardLayout, "init seeds it")
        for ime in self.ime_dirs:
            self.assertEqual(0, self.shipped(ime)["keyboardLayout"],
                             "the shipped JSON of %s carries it" % ime)
        self.assertIn("name=\"keyboardLayout\"", self.script, "the page radio follows")
        self.assertNotIn("keyboardLayout", TABLE_AFFECTING_KEYS)

    def test_invalid_values_fall_back_and_sel_key_rows(self):
        cfg = fresh_config()

        cfg.candFontName = ""
        cfg.sanitize()
        self.assertEqual("MingLiu", cfg.candFontName)
        cfg.candFontName = None
        cfg.sanitize()
        self.assertEqual("MingLiu", cfg.candFontName)
        cfg.candFontName = "  Noto Sans TC  "
        cfg.sanitize()
        self.assertEqual("Noto Sans TC", cfg.candFontName)

        cfg.leadInKey = ""
        cfg.sanitize()
        self.assertEqual("`", cfg.leadInKey)
        cfg.leadInKey = 3
        cfg.sanitize()
        self.assertEqual("3", cfg.leadInKey)

        cfg.selKeyType = 99
        cfg.sanitize()
        self.assertEqual(0, cfg.selKeyType)
        cfg.selKeyType = "x"
        cfg.sanitize()
        self.assertEqual(0, cfg.selKeyType)

        cfg.enableCtrlSymbols = "yes"
        cfg.sanitize()
        self.assertIs(True, cfg.enableCtrlSymbols)

        cfg.selKeyType = 1
        self.assertEqual("0123456789", cfg.getSelKeys())
        cfg.selKeyType = 0
        self.assertEqual("1234567890", cfg.getSelKeys())


class CinbaseConfigReadSiteTests(CinbaseKeyHarness):

    def test_the_engine_reads_each_value(self):
        service = self.activate_chesimplex()

        self.assertEqual("MingLiu",
                         self.drain(service)["customizeUI"]["candFontName"])
        self.assertEqual(service.cfg.getSelKeys(), service.selKeys)
        self.assertEqual("`", service.leadInKey)
        self.assertIs(True, service.enableCtrlSymbols)

    def test_a_configured_font_name_reaches_the_candidate_window(self):
        service = self.activate_chesimplex()
        service.cfg.candFontName = "Noto Sans TC"

        reply = service.cinbase.applyConfig(service)

        self.assertEqual("Noto Sans TC",
                         reply["customizeUI"]["candFontName"])


class ChewingConfigReadSiteTests(unittest.TestCase):
    # #582 names both candidate-drawing paths: the cinbase window above and the
    # chewing window, whose applyConfig() used to pass the literal 'MingLiu'.

    def test_the_chewing_config_ships_the_font_default(self):
        from input_methods.chewing import chewing_config

        with tempfile.TemporaryDirectory() as temp_dir:
            with mock.patch.dict(os.environ, {"APPDATA": temp_dir}):
                cfg = chewing_config.ChewingConfig()
                self.assertEqual(chewing_config.DEF_FONT_NAME, cfg.candFontName)
                # a saved empty value falls back instead of reaching the UI
                with open(cfg.getConfigFile(), "w", encoding="utf-8") as handle:
                    json.dump({"candFontName": ""}, handle)
                cfg.candFontName = "stale"
                cfg.load()
                self.assertEqual(chewing_config.DEF_FONT_NAME, cfg.candFontName)

    def test_the_configured_font_reaches_the_chewing_window(self):
        from input_methods.chewing import chewing_config, chewing_ime

        context = mock.MagicMock()
        service = chewing_ime.ChewingTextService.__new__(
            chewing_ime.ChewingTextService)
        service.isActivated = False
        service.configVersion = None
        service.chewingContext = context
        service.currentReply = {}
        service.opencc = None
        service.hasLangButtons = False
        service.updateSwitchLangIcon = False
        service.langMode = context.get_ChiEngMode.return_value
        service.shapeMode = context.get_ShapeMode.return_value
        service.icon_dir = "icons"
        service.client = mock.MagicMock(isWindows8Above=False)

        cfg = chewing_config.chewingConfig
        previous = cfg.candFontName
        cfg.candFontName = "Noto Sans TC"
        try:
            chewing_ime.ChewingTextService.applyConfig(service)
        finally:
            cfg.candFontName = previous

        self.assertEqual("Noto Sans TC",
                         service.handleRequest({"seqNum": 0})["customizeUI"]["candFontName"])


